#!/usr/bin/env node
// D6: generate typed API definitions from docs/api/*.openapi.yaml (read-only input).
//   node scripts/gen-api.mjs                 write src/api/generated/*.ts
//   node scripts/gen-api.mjs --check         exit 1 if any generated file differs (AC-9.5)
//   --out <dir>                              use another output directory (tests)
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const here = dirname(fileURLToPath(import.meta.url));
const contractsDir = resolve(here, '../../docs/api');
const services = ['api-gateway', 'auth-service', 'report-service', 'scenario-service'];

function parseArgs(argv) {
  const args = { check: false, out: resolve(here, '../src/api/generated') };
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--check') args.check = true;
    else if (argv[i] === '--out') {
      const value = argv[i + 1];
      if (!value) throw new Error('--out needs a directory');
      args.out = resolve(value);
      i += 1;
    } else throw new Error(`Unknown argument: ${argv[i]}`);
  }
  return args;
}

async function generate(service) {
  const source = join(contractsDir, `${service}.openapi.yaml`);
  const ast = await openapiTS(pathToFileURL(source));
  const header =
    `// Generated by scripts/gen-api.mjs from docs/api/${service}.openapi.yaml. Do not edit; run "npm run gen:api".\n` +
    '/* eslint-disable */\n';
  return header + astToString(ast);
}

async function main() {
  const { check, out } = parseArgs(process.argv.slice(2));
  const drift = [];
  if (!check) mkdirSync(out, { recursive: true });
  for (const service of services) {
    const file = join(out, `${service}.ts`);
    const fresh = await generate(service);
    if (check) {
      if (!existsSync(file)) drift.push(`${service}.ts (missing)`);
      else if (readFileSync(file, 'utf8') !== fresh) drift.push(`${service}.ts (differs)`);
    } else {
      writeFileSync(file, fresh);
    }
  }
  if (check) {
    const expected = new Set(services.map((s) => `${s}.ts`));
    const extra = existsSync(out) ? readdirSync(out).filter((f) => !expected.has(f)) : [];
    for (const f of extra) drift.push(`${f} (unexpected)`);
    if (drift.length > 0) {
      process.stderr.write(
        `gen:api:check failed: src/api/generated is out of date with docs/api.\n  ${drift.join('\n  ')}\nRun "npm run gen:api".\n`,
      );
      process.exit(1);
    }
    process.stdout.write('gen:api:check: generated client matches docs/api.\n');
  }
}

main().catch((error) => {
  process.stderr.write(`gen-api failed: ${error instanceof Error ? error.message : String(error)}\n`);
  process.exit(1);
});
